+    public File getLicensesDir() {
+        return licensesDir;
+    }
+
+    public void setLicensesDir(File licensesDir) {
+        this.licensesDir = licensesDir;
+    }
+
+    public File getOutputFile() {
+        return outputFile;
+    }
