+        Map<Integer, long[]> indexedPoints = new HashMap<>(numGroups);
+        Map<Integer, double[]> indexedSortValues = new HashMap<>(numGroups);
+        for (int groupOrd = 0; groupOrd < numGroups; groupOrd++) {
+            int numPoints = randomIntBetween(2, 2 * size);
