+        extendedNamedXContents.add(new NamedXContentRegistry.Entry(Aggregation.class,
+            new ParseField(GeoLineAggregationBuilder.NAME),
+            (p, c) -> {
+                assumeTrue("There is no ParsedGeoLine yet", false);
+                return null;
+            }
+        ));
+        return extendedNamedXContents;
+    }
